def replace_spaces(string):
    result = []
    i = 0
    while i < len(string):
        if string[i] == ' ':
            result.append('%20')
            i += 1
        elif string[i] == '%':
            result.append('%25')
            i += 1
        else:
            result.append(string[i])
            i += 1
    return ''.join(result)
```

